def check(args, got, expected):
    import collections
    nums = args[0]
    if not isinstance(got, list):
        return False

    class N:
        __slots__ = ("val", "left", "right")

        def __init__(self, v):
            self.val, self.left, self.right = v, None, None

    if not got:
        return not nums
    it = iter(got)
    root = N(next(it))
    q = collections.deque([root])
    while q:
        node = q.popleft()
        stop = False
        for side in ("left", "right"):
            try:
                v = next(it)
            except StopIteration:
                stop = True
                break
            if v is not None:
                c = N(v)
                setattr(node, side, c)
                q.append(c)
        if stop:
            break
    out, st, cur = [], [], root
    while st or cur:
        while cur:
            st.append(cur)
            cur = cur.left
        cur = st.pop()
        out.append(cur.val)
        cur = cur.right
    if out != nums:
        return False

    height, stack = {None: 0}, [(root, False)]      # iterative post-order: safe on very deep trees
    while stack:
        n, done = stack.pop()
        if n is None:
            continue
        if done:
            a, b = height[n.left], height[n.right]
            if abs(a - b) > 1:
                return False
            height[n] = 1 + max(a, b)
        else:
            stack.append((n, True))
            stack.append((n.left, False))
            stack.append((n.right, False))
    return True

