                v = next(it)
            except StopIteration:
                stop = True
                break
            if v is not None:
                c = N(v)
                setattr(node, side, c)
                q.append(c)
        if stop:
            break
    out, st, cur = [], [], root
    while st or cur:
        while cur:
            st.append(cur)
            cur = cur.left
        cur = st.pop()
        out.append(cur.val)
        cur = cur.right
    if out != nums:
        return False

    height, stack = {None: 0}, [(root, False)]      # iterative post-order: safe on very deep trees
    while stack:
        n, done = stack.pop()
        if n is None:
            continue
        if done:
            a, b = height[n.left], height[n.right]
            if abs(a - b) > 1:
                return False
            height[n] = 1 + max(a, b)
        else:
            stack.append((n, True))
            stack.append((n.left, False))
            stack.append((n.right, False))
    return True

